import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession} from '../../types/session.js';
import type {SessionStore, SessionListOptions} from '../../types/sessionStore.js';
import type {OutgoingMessage} from '../../types/messages.js';

// A list request is not a turn: it is answered from the session's own userId and never reaches the orchestrator.

const harness = (listFor?: SessionStore['listFor']) => {
  const sent: OutgoingMessage[] = [];
  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const store = {listFor} as unknown as SessionStore;
  const handle = createMessageHandler({} as ChatOrchestrator, store);
  return {sent, send: (raw: unknown) => handle(ws, session, raw)};
};

describe('list_sessions in the websocket message handler', () => {
  it('lists the connection user, forwarding limit and before, with dates as ISO strings', async () => {
    const seen: Array<{userId: string | number; options?: SessionListOptions}> = [];
    const at = new Date('2026-01-01T00:00:00.000Z');
    const h = harness((userId, options) => {
      seen.push({userId, options});
      return [{sessionId: 's2', createdAt: at, updatedAt: at, entryCount: 3}];
    });
    const before = {updatedAt: '2026-01-02T00:00:00.000Z', sessionId: 's3'};

    await h.send({type: 'list_sessions', limit: 5, before, userId: 'u2'});

    expect({seen, sent: h.sent}).toEqual({
      seen: [{userId: 'u1', options: {limit: 5, before}}],
      sent: [
        {
          type: 'session_list',
          sessions: [{sessionId: 's2', createdAt: at.toISOString(), updatedAt: at.toISOString(), entryCount: 3}],
        },
      ],
    });
  });

  it('answers an empty list when the store has no listFor', async () => {
    const h = harness();

    await h.send({type: 'list_sessions'});

    expect(h.sent).toEqual([{type: 'session_list', sessions: []}]);
  });

  it('answers SERVER_ERROR without store detail when listFor rejects', async () => {
    const h = harness(() => Promise.reject(new Error('database offline')));

    await h.send({type: 'list_sessions'});

    expect(h.sent).toEqual([{type: 'error', code: 'SERVER_ERROR', message: 'Failed to list sessions'}]);
  });
});
